import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register } from 'claude-code'

import type { BandUi, GitFile, GitSnap } from '../types'

const snapAtom = atom({ plugin: 'git-sync-band', key: 'snap' } as const, null)
const uiAtom = atom({ plugin: 'git-sync-band', key: 'ui' } as const, {
  isExpanded: false,
  busy: null,
  pending: null,
})

const HUMAN = new Set(['composer', 'bridge', 'sdk', 'unclassified'])
// No credential prompts (there is no terminal to answer them), and no index
// lock for a status check, so the band never collides with Claude's own git.
const GIT_ENV = {
  GIT_TERMINAL_PROMPT: '0',
  GCM_INTERACTIVE: 'never',
  GIT_OPTIONAL_LOCKS: '0',
  GIT_SSH_COMMAND: 'ssh -o BatchMode=yes',
}
const STATUS_EVERY_MS = 60_000
const FETCH_EVERY_MS = 5 * 60_000
// Before a prompt, fetch again when the last fetch is older than this.
const FETCH_STALE_MS = 2 * 60_000
const SENSITIVE =
  /(^|\/)(\.env(\.[\w.-]+)?|[^/]*\.(pem|key|pfx|p12|jks|keystore|ppk)|id_(rsa|ed25519|ecdsa)[^/]*|[^/]*credentials[^/]*\.json|[^/]*secrets?\.(json|ya?ml|env|txt)|\.npmrc|\.netrc)$/i
const NOT_SENSITIVE = /\.env\.(example|sample|template|defaults)$/i
const COMMIT_SYSTEM =
  'You write git commit messages. Reply with the message only: a subject line under 72 characters ' +
  'in the imperative mood, then optionally a blank line and up to four short "- " lines. ' +
  'No quotes, no code fences, no trailers or attribution lines.'

type Ran = { ok: boolean; out: string; err: string }

let lastFetchAt = 0
let inflight: Promise<GitSnap | null> | undefined
let debounce: { cancel: () => void } | undefined

const firstLine = (text: string) =>
  text.split('\n').map(line => line.trim()).find(Boolean) ?? 'unknown error'

const ago = (ms: number) => {
  const m = Math.round(ms / 60_000)
  if (m < 1) return 'just now'
  if (m < 60) return `${m}m ago`
  const h = Math.round(m / 60)

  return h < 48 ? `${h}h ago` : `${Math.round(h / 24)}d ago`
}

const plural = (n: number, one: string) => `${n} ${one}${n === 1 ? '' : 's'}`

// The band's pictures are drawn as images, which can't read the app's theme,
// so their colors are mid-tones that hold on light and dark alike: the cache
// band's grey and orange, with its amber and red for trouble.
const INK = '#A3A095'
const ACCENT = '#F28B54'
const AMBER = '#DFA13A'
const RED = '#E5534B'
const iconSvg = (paths: string, ink: string) =>
  `<svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="${ink}" ` +
  `stroke-width="2" stroke-linecap="round" stroke-linejoin="round">${paths}</svg>`
const BRANCH =
  '<circle cx="6" cy="6" r="2.4"/><circle cx="6" cy="18" r="2.4"/><circle cx="18" cy="6" r="2.4"/>' +
  '<path d="M6 8.4v7.2M18 8.4c0 5-5 6.6-9.6 8.6"/>'
const FILES =
  '<path d="M14 3H7a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h10a2 2 0 0 0 2-2V8z"/><path d="M14 3v5h5M9 13h6M9 17h4"/>'
const PULL = '<path d="M12 4v11M7.5 10.5 12 15l4.5-4.5M5 20h14"/>'
const PUSH = '<path d="M12 15V4M7.5 8.5 12 4l4.5 4.5M5 20h14"/>'
const CHECK = '<path d="M5 12.5 10 17.5 19 7"/>'
const CROSS = '<path d="M6 6l12 12M18 6 6 18"/>'

// The branch icon's color says the state at a glance: red for a conflict or
// an operation half done, amber when behind, orange with something to commit
// or push, grey when clean and in step.
const branchInk = (snap: GitSnap) =>
  snap.op !== null || snap.conflicted > 0
    ? RED
    : snap.behind > 0
      ? AMBER
      : snap.files.length > 0 || snap.ahead > 0 || snap.upstream === null
        ? ACCENT
        : INK

// A picture takes no click, so each one a person presses has a blank button
// laid over it and centered on it, two blank Braille cells wide.
const ICON_BLANK = '⠀⠀'

// Widths in the band's cells, to pick the fullest layout that fits one row,
// as the cache band does: its sans text runs about three quarters of a cell a
// character, and a cell is about 7.8 pixels.
const textCells = (text: string) => text.length * 0.75
const pxCells = (px: number) => px / 7.8
const PAD = pxCells(12)
const ICON_BUTTON = pxCells(30)

function parseStatus(raw: string) {
  const items = raw.split('\0')
  const files: GitFile[] = []
  let branch = ''
  let upstream: string | null = null
  let ahead = 0
  let behind = 0
  let conflicted = 0

  for (let i = 0; i < items.length; i++) {
    const item = items[i] ?? ''
    if (item.startsWith('# branch.head ')) branch = item.slice(14)
    else if (item.startsWith('# branch.upstream ')) upstream = item.slice(18)
    else if (item.startsWith('# branch.ab ')) {
      const m = /\+(\d+) -(\d+)/.exec(item)
      ahead = Number(m?.[1] ?? 0)
      behind = Number(m?.[2] ?? 0)
    } else if (item.startsWith('1 ') || item.startsWith('2 ')) {
      const fields = item.split(' ')
      const isRename = item.startsWith('2 ')
      files.push({
        code: (fields[1] ?? '..').replace(/\./g, ' '),
        path: fields.slice(isRename ? 9 : 8).join(' '),
      })
      // With -z a rename's original path is the next item.
      if (isRename) i++
    } else if (item.startsWith('u ')) {
      conflicted++
      files.push({ code: 'UU', path: item.split(' ').slice(10).join(' ') })
    } else if (item.startsWith('? ')) {
      files.push({ code: '??', path: item.slice(2) })
    }
  }

  return { branch, upstream, ahead, behind, conflicted, files }
}

async function git(
  $: EngineInterface,
  cwd: string,
  args: string[],
  timeoutMs = 30_000,
  stdin?: string,
): Promise<Ran> {
  try {
    const r = await $.process.run(['git', ...args], { cwd, env: GIT_ENV, timeoutMs, stdin })

    return { ok: r.exitCode === 0, out: r.stdout, err: r.stderr }
  } catch (error) {
    return { ok: false, out: '', err: String(error) }
  }
}

async function opOf($: EngineInterface, gitDir: string) {
  const marks: [string, string][] = [
    ['rebase-merge', 'rebase'],
    ['rebase-apply', 'rebase'],
    ['MERGE_HEAD', 'merge'],
    ['CHERRY_PICK_HEAD', 'cherry-pick'],
    ['REVERT_HEAD', 'revert'],
  ]
  for (const [file, op] of marks) {
    if (await $.fs.exists(`${gitDir}/${file}`)) return op
  }

  return null
}

async function load($: EngineInterface, doFetch: boolean, fetchTimeoutMs: number) {
  const cwd = await $.session.cwd()
  const top = await git($, cwd, ['rev-parse', '--show-toplevel'])
  if (!top.ok) {
    await update($, snapAtom, () => null)

    return null
  }
  const root = top.out.trim()

  if (doFetch) {
    lastFetchAt = await $.clock.now()
    await git($, root, ['fetch', '--quiet', '--no-tags'], fetchTimeoutMs)
  }

  const status = await git($, root, [
    'status',
    '--porcelain=v2',
    '--branch',
    '-z',
    '--untracked-files=normal',
  ])
  if (!status.ok) return read($, snapAtom)

  const gitDir = await git($, root, ['rev-parse', '--absolute-git-dir'])
  const snap: GitSnap = {
    root,
    ...parseStatus(status.out),
    op: gitDir.ok ? await opOf($, gitDir.out.trim()) : null,
    pushedAt: Number(await $.store.get(`pushedAt:${root}`)) || null,
    checkedAt: await $.clock.now(),
  }
  await update($, snapAtom, () => snap)

  return snap
}

async function refresh($: EngineInterface, doFetch = false, fetchTimeoutMs = 60_000) {
  while (inflight) await inflight.catch(() => null)
  inflight = load($, doFetch, fetchTimeoutMs)
  try {
    return await inflight
  } finally {
    inflight = undefined
  }
}

function refreshSoon($: EngineInterface) {
  debounce?.cancel()
  debounce = $.clock.after(2_000, () => {
    debounce = undefined
    void refresh($)
  })
}

async function markPushed($: EngineInterface, root: string) {
  await $.store.set(`pushedAt:${root}`, await $.clock.now())
}

async function setUi($: EngineInterface, patch: Partial<BandUi>) {
  await update($, uiAtom, ui => ({ ...ui, ...patch }))
}

// Before a person's prompt: fast-forward when that cannot lose anything, and
// tell Claude what came in (or why nothing did).
async function syncBefore($: EngineInterface, snap: GitSnap) {
  if (!snap.upstream || snap.behind === 0) return undefined

  const isDirty = snap.files.some(f => f.code !== '??')
  const why = snap.op
    ? `a ${snap.op} is in progress`
    : isDirty
      ? 'there are uncommitted changes'
      : snap.ahead > 0
        ? `it also has ${plural(snap.ahead, 'local commit')} origin does not have`
        : null
  if (why) {
    $.ui.toast(`${snap.branch} is ${snap.behind} behind ${snap.upstream}; not pulled because ${why}.`, {
      timeoutMs: 8_000,
    })

    return `[git-sync-band] ${snap.branch} is ${plural(snap.behind, 'commit')} behind ${snap.upstream} and was not pulled automatically because ${why}.`
  }

  const before = await git($, snap.root, ['rev-parse', 'HEAD'])
  const pull = await git($, snap.root, ['pull', '--ff-only', '--quiet'], 120_000)
  if (!pull.ok) {
    $.ui.toast(`Pull failed: ${firstLine(pull.err)}`, { timeoutMs: 8_000 })

    return `[git-sync-band] Tried to fast-forward ${snap.branch} to ${snap.upstream} before this prompt, and it failed: ${firstLine(pull.err)}`
  }

  const log = await git($, snap.root, [
    'log',
    '--oneline',
    '--no-decorate',
    '-n',
    '15',
    `${before.out.trim()}..HEAD`,
  ])
  await refresh($)
  $.ui.toast(`Pulled ${plural(snap.behind, 'commit')} from ${snap.upstream}.`)

  return `[git-sync-band] Before this prompt, ${snap.branch} was fast-forwarded to ${snap.upstream} (${plural(snap.behind, 'new commit')}):\n${log.out.trim()}`
}

async function pullNow($: EngineInterface) {
  const snap = await read($, snapAtom)
  if (!snap) return
  await setUi($, { busy: 'Pulling…' })
  const r = await git($, snap.root, ['pull', '--ff-only', '--quiet'], 120_000)
  await setUi($, { busy: null })
  $.ui.toast(r.ok ? `Pulled from ${snap.upstream}.` : `Pull failed: ${firstLine(r.err)}`, {
    timeoutMs: 8_000,
  })
  await refresh($)
}

async function commitMessage($: EngineInterface, snap: GitSnap, newFiles: string[]) {
  const [stat, diff, recent] = await Promise.all([
    git($, snap.root, ['diff', 'HEAD', '--stat', '--no-color']),
    git($, snap.root, ['diff', 'HEAD', '--no-color', '-U1']),
    git($, snap.root, ['log', '--oneline', '--no-decorate', '-n', '8']),
  ])
  const prompt = [
    `Recent commit subjects here, match their style:\n${recent.out.trim() || '(none)'}`,
    `Changed files:\n${stat.out.trim() || '(none tracked)'}`,
    newFiles.length > 0 ? `New files:\n${newFiles.slice(0, 40).join('\n')}` : '',
    `Diff, possibly cut:\n${diff.out.slice(0, 12_000)}`,
  ]
    .filter(Boolean)
    .join('\n\n')
  const r = await $.model.complete({
    model: 'haiku',
    system: COMMIT_SYSTEM,
    prompt,
    maxTokens: 300,
    timeoutMs: 20_000,
  })
  const text = r.isAnswered ? r.text.replace(/^```\w*\n?|\n?```$/g, '').trim() : ''
  if (text) return text

  const names = snap.files.slice(0, 3).map(f => f.path.split('/').pop())

  return `Update ${plural(snap.files.length, 'file')}: ${names.join(', ')}${snap.files.length > 3 ? ', …' : ''}`
}

async function startCommit($: EngineInterface) {
  const snap = await refresh($)
  if (!snap) return
  if (snap.op || snap.conflicted > 0) {
    $.ui.toast(`Not committing: ${snap.op ? `a ${snap.op} is in progress` : 'there are conflicts'}.`)

    return
  }
  if (snap.files.length === 0) {
    await setUi($, { pending: { message: '', files: 0 } })

    return
  }

  // Every untracked file, not just their folders, so a new .env in a new
  // folder is caught too.
  const all = await git($, snap.root, ['status', '--porcelain', '-z', '--untracked-files=all'])
  const paths = all.out
    .split('\0')
    .filter(Boolean)
    .map(entry => entry.slice(3))
  const risky = paths.filter(p => SENSITIVE.test(p) && !NOT_SENSITIVE.test(p))
  if (risky.length > 0) {
    $.ui.toast(
      `Not committing: ${risky.slice(0, 3).join(', ')} ${risky.length === 1 ? 'looks' : 'look'} like secrets. ` +
        'Add to .gitignore, or commit by hand.',
      { timeoutMs: 12_000 },
    )

    return
  }

  await setUi($, { busy: 'Writing a commit message…' })
  const newFiles = all.out
    .split('\0')
    .filter(entry => entry.startsWith('??'))
    .map(entry => entry.slice(3))
  const message = await commitMessage($, snap, newFiles)
  await setUi($, { busy: null, pending: { message, files: snap.files.length } })
}

async function confirmCommit($: EngineInterface) {
  const ui = await read($, uiAtom)
  const pending = ui.pending
  if (!pending) return

  const snap = await refresh($)
  if (!snap) return
  if (snap.files.length !== pending.files) {
    $.ui.toast('Files changed since the message was written; writing it again.')
    await setUi($, { pending: null })
    await startCommit($)

    return
  }

  await setUi($, { pending: null, busy: pending.files > 0 ? 'Committing…' : 'Pushing…' })
  if (pending.files > 0) {
    const add = await git($, snap.root, ['add', '-A'])
    const commit = add.ok
      ? await git($, snap.root, ['commit', '--quiet', '-F', '-'], 60_000, `${pending.message}\n`)
      : add
    if (!commit.ok) {
      await setUi($, { busy: null })
      $.ui.toast(`Commit failed: ${firstLine(commit.err || commit.out)}`, { timeoutMs: 12_000 })
      await refresh($)

      return
    }
  }

  await setUi($, { busy: 'Pushing…' })
  const args = snap.upstream ? ['push', '--quiet'] : ['push', '--quiet', '-u', 'origin', 'HEAD']
  const push = await git($, snap.root, args, 120_000)
  await setUi($, { busy: null, isExpanded: false })
  if (!push.ok) {
    $.ui.toast(
      `${pending.files > 0 ? 'Committed, but the push' : 'Push'} failed: ${firstLine(push.err)}`,
      { timeoutMs: 12_000 },
    )
    await refresh($)

    return
  }

  await markPushed($, snap.root)
  const head = await git($, snap.root, ['log', '-1', '--format=%h %s'])
  const target = snap.upstream ?? `origin/${snap.branch}`
  $.ui.toast(`Pushed to ${target}: ${head.out.trim()}`)
  $.ui.log(`git-sync-band: pushed ${head.out.trim()} to ${target}`)
  await refresh($)
}

export const register: Register = on => {
  on('session.start', async ($, e, next) => {
    void refresh($, true)
    $.clock.every(STATUS_EVERY_MS, () => void refresh($))
    $.clock.every(FETCH_EVERY_MS, () => void refresh($, true))

    return next(e)
  })

  on('prompt.submit', async ($, e, next) => {
    // Only a person's prompt, typed while Claude is idle: never pull under a running turn.
    if (!HUMAN.has(e.origin.kind) || e.turnId) return next(e)

    const now = await $.clock.now()
    const snap = await refresh($, now - lastFetchAt > FETCH_STALE_MS, 20_000)
    const note = snap ? await syncBefore($, snap) : undefined

    return next(note ? { ...e, context: [...(e.context ?? []), note] } : e)
  })

  on('tool.call', async ($, e, next) => {
    const ran = await next(e)
    const command =
      e.tool === 'Bash' || e.tool === 'PowerShell'
        ? String((e as { command?: unknown }).command ?? '')
        : ''
    if (command && /\bgit\b[^\n|;&]*\bpush\b/.test(command) && ran.deny === undefined && ran.isError !== true) {
      const snap = await read($, snapAtom)
      if (snap) await markPushed($, snap.root)
    }
    if (command || e.tool === 'Edit' || e.tool === 'Write' || e.tool === 'NotebookEdit') {
      refreshSoon($)
    }

    return ran
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    if (!e.agentId) void refresh($)

    return done
  })

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey) return next(e)
    const snap = await read($, snapAtom)
    if (!snap) return next(e)

    const ui = await read($, uiAtom)
    const now = await $.clock.now()
    const table = $.ui.resolve(e)
    const { Box, Button, Text } = table
    // The terminal draws no pictures: words there, and the keys it can press.
    const Svg = e.surface !== 'terminal' && 'Svg' in table ? table.Svg : undefined
    const isTerminal = Svg === undefined
    const below = await next(e)

    const changed = snap.files.length
    const isIdle = !e.props.isWorking && !ui.busy && !ui.pending
    const canCommit = !snap.op && snap.conflicted === 0 && (changed > 0 || snap.ahead > 0)
    const listRows = Math.max(1, e.props.maxRows - (ui.pending ? 5 : 2))
    const target = snap.upstream ?? `origin/${snap.branch}`

    // What the row says, each piece with its color; the pushed time goes first
    // when the band is short of room.
    const pieces = [
      snap.upstream === null ? { text: 'not on remote', color: undefined } : null,
      snap.behind > 0 ? { text: `↓${snap.behind} behind`, color: 'warning' } : null,
      snap.ahead > 0 ? { text: `↑${snap.ahead} to push`, color: 'permission' } : null,
      snap.upstream !== null && snap.ahead === 0 && snap.behind === 0 ? { text: 'in sync', color: undefined } : null,
      { text: changed > 0 ? `${changed} changed` : 'clean', color: undefined },
      snap.conflicted > 0 ? { text: plural(snap.conflicted, 'conflict'), color: 'error' } : null,
      snap.op !== null ? { text: `${snap.op} in progress`, color: 'error' } : null,
      ui.busy !== null ? { text: ui.busy, color: 'warning' } : null,
    ].filter(piece => piece !== null)
    const pushed = snap.pushedAt !== null ? `pushed ${ago(now - snap.pushedAt)}` : null

    const actions = [
      {
        key: 'files',
        name: ui.isExpanded ? 'Hide files' : 'Files',
        paths: FILES,
        ink: INK,
        hotkey: 'f',
        shows: changed > 0,
        onPress: () => void update($, uiAtom, u => ({ ...u, isExpanded: !u.isExpanded })),
      },
      {
        key: 'pull',
        name: 'Pull',
        paths: PULL,
        ink: INK,
        hotkey: 'p',
        shows: isIdle && snap.behind > 0,
        onPress: () => void pullNow($),
      },
      {
        key: 'commit',
        name: changed > 0 ? 'Commit & push' : 'Push',
        paths: PUSH,
        ink: ACCENT,
        hotkey: 'c',
        shows: isIdle && canCommit,
        onPress: () => void startCommit($),
      },
    ].filter(action => action.shows)

    // The fullest layout that fits one row: every word; then without the
    // pushed time and the buttons' names; then icons alone, the words in
    // hover cards. The terminal keeps its words.
    const columns = e.props.bodyColumns
    const statusCells = pieces.reduce((sum, piece) => sum + 1 + textCells(`· ${piece.text}`), 0)
    const leftCells = (Svg ? pxCells(16) + 1 : textCells('git ')) + textCells(snap.branch) + statusCells
    // Files is its icon alone; the others are named where there's room.
    const isNamed = (key: string) => key !== 'files'
    const namedCells = actions.reduce(
      (sum, action) =>
        sum + (isNamed(action.key) ? (Svg ? ICON_BUTTON + 1 : 0) + textCells(action.name) + PAD : ICON_BUTTON) + 2,
      0,
    )
    const iconCells = actions.length * (ICON_BUTTON + 1)
    const fullCells = Math.ceil(leftCells + (pushed ? 1 + textCells(`· ${pushed}`) : 0) + 3 + namedCells)
    const mediumCells = Math.ceil(leftCells + 3 + iconCells)
    const layout = isTerminal || columns >= fullCells ? 'full' : columns >= mediumCells ? 'medium' : 'icons'
    const isIcons = layout === 'icons'
    const hasNames = layout === 'full'

    // A card that opens while the pointer is over the keyed Box around it.
    const card = (...lines: string[]) => (
      <Box
        position="absolute"
        top={-4}
        left={0}
        display="none"
        hover={{ display: 'flex' }}
        flexDirection="column"
        borderStyle="round"
        borderColor="subtle"
        backgroundColor="background"
        paddingX={1}
      >
        {lines.map(line => (
          <Text>{line}</Text>
        ))}
      </Box>
    )

    // An icon a person presses: a blank button laid over the picture takes the
    // click, and its hover frames it.
    const pressable = (key: string, paths: string, ink: string, onPress: () => void, tip?: string) => (
      <Box key={`${key}-box`} position="relative" flexDirection="row" alignItems="center" flexShrink={0}>
        {Svg && <Svg source={iconSvg(paths, ink)} alt={tip ?? key} width={16} height={16} />}
        <Box
          position="absolute"
          top={0}
          left={0}
          right={0}
          height="100%"
          flexDirection="row"
          alignItems="center"
          justifyContent="center"
        >
          <Button key={key} label={ICON_BLANK} plain onPress={onPress} />
        </Box>
        {tip !== undefined && card(tip)}
      </Box>
    )

    // An action: its icon and name where there's room, the icon alone (named
    // in a hover card) where there isn't, a key and a name on the terminal.
    const action = (a: (typeof actions)[number], withName: boolean) => {
      if (isTerminal) {
        return <Button key={a.key} label={a.name} hotkey={a.hotkey} plain onPress={a.onPress} />
      }
      if (!withName) return pressable(a.key, a.paths, a.ink, a.onPress, a.name)

      return (
        <Box key={`${a.key}-named`} flexDirection="row" alignItems="center" columnGap={1} flexShrink={0}>
          {pressable(`${a.key}-icon`, a.paths, a.ink, a.onPress)}
          <Button key={a.key} label={a.name} plain onPress={a.onPress} />
        </Box>
      )
    }

    const summary = [snap.branch, ...pieces.map(piece => piece.text), ...(pushed ? [pushed] : [])].join(' · ')

    const branch = (
      <Box key="branch" flexDirection="row" alignItems="center" columnGap={1} flexShrink={0}>
        {Svg ? (
          <Box flexShrink={0}>
            <Svg source={iconSvg(BRANCH, branchInk(snap))} alt={`Branch ${snap.branch}`} width={16} height={16} />
          </Box>
        ) : (
          <Text dimColor>git</Text>
        )}
        {!isIcons && (
          <Text bold wrap="truncate">
            {snap.branch}
          </Text>
        )}
        {!isIcons &&
          pieces.map(piece => (
            <Text color={piece.color} dimColor={piece.color === undefined} wrap="truncate">
              · {piece.text}
            </Text>
          ))}
        {hasNames && pushed !== null && (
          <Text dimColor wrap="truncate">
            · {pushed}
          </Text>
        )}
        {isIcons && card(summary)}
      </Box>
    )

    const pending = ui.pending
    const question =
      pending === null
        ? ''
        : pending.files > 0
          ? `Commit ${plural(pending.files, 'file')} on ${snap.branch} and push to ${target}:`
          : `Push ${plural(snap.ahead, 'commit')} to ${target}?`
    const confirm = {
      key: 'confirm',
      name: pending !== null && pending.files > 0 ? 'Commit & push' : 'Push',
      paths: CHECK,
      ink: ACCENT,
      hotkey: 'y',
      shows: true,
      onPress: () => void confirmCommit($),
    }
    const cancel = {
      key: 'cancel',
      name: 'Cancel',
      paths: CROSS,
      ink: INK,
      hotkey: 'n',
      shows: true,
      onPress: () => void update($, uiAtom, u => ({ ...u, pending: null })),
    }

    return (
      <Box flexDirection="column">
        {/* The line between the cache band's row and this one: box-drawing
            cells, drawn in the code font a cell each, so the band's width in
            cells spans it exactly. */}
        <Text color="subtle" wrap="truncate">
          {'─'.repeat(Math.max(1, columns))}
        </Text>
        <Box
          flexDirection="row"
          flexWrap="wrap"
          alignItems="center"
          justifyContent="space-between"
          width="100%"
          columnGap={isIcons ? 2 : 3}
        >
          {branch}
          <Box key="git-actions" flexDirection="row" alignItems="center" columnGap={hasNames ? 2 : 1}>
            {actions.map(a => action(a, hasNames && isNamed(a.key)))}
          </Box>
        </Box>
        {pending !== null && (
          <Box key="git-confirm" flexDirection="column">
            <Text dimColor wrap="truncate-end">
              {question}
            </Text>
            {pending.message !== '' && <Text bold>{pending.message}</Text>}
            <Box flexDirection="row" alignItems="center" columnGap={2}>
              {action(confirm, true)}
              {action(cancel, true)}
            </Box>
          </Box>
        )}
        {ui.isExpanded && pending === null && (
          <Box key="git-files" flexDirection="column">
            {snap.files.slice(0, listRows).map(f => (
              <Text key={f.path} wrap="truncate-middle">
                <Text color={f.code === '??' ? 'green' : f.code.includes('D') ? 'red' : 'yellow'}>
                  {f.code.padEnd(2)}
                </Text>{' '}
                {f.path}
              </Text>
            ))}
            {changed > listRows && <Text dimColor>+{changed - listRows} more</Text>}
          </Box>
        )}
        {below}
      </Box>
    )
  })
}

