export type GitFile = { code: string; path: string }

export type GitSnap = {
  root: string
  branch: string
  upstream: string | null
  ahead: number
  behind: number
  conflicted: number
  files: GitFile[]
  op: string | null
  pushedAt: number | null
  checkedAt: number
}

export type PendingCommit = { message: string; files: number }

export type BandUi = {
  isExpanded: boolean
  busy: string | null
  pending: PendingCommit | null
}

